1	//! The pluggable [`ExecutionBackend`] that [`crate::BashTool`] runs against, and
2	//! the shared types describing a backend's *containment* (distinct from the
3	//! runner's *approval* policy and from resource-capping).
4	
5	use std::path::PathBuf;
6	use std::time::Duration;
7	
8	use async_trait::async_trait;
9	use paigasus_helikon_core::ToolError;
10	
11	mod host;
12	pub use host::{HostBackend, HostBackendBuilder};
13	
14	#[cfg(all(
15	    feature = "os-sandbox",
16	    target_os = "linux",
17	    any(target_arch = "x86_64", target_arch = "aarch64")
18	))]
19	mod os_sandbox;
20	#[cfg(all(
21	    feature = "os-sandbox",
22	    target_os = "linux",
23	    any(target_arch = "x86_64", target_arch = "aarch64")
24	))]
25	pub use os_sandbox::{OsSandboxBackend, OsSandboxBackendBuilder, OsSandboxError};
26	
27	/// Default wall-clock timeout for a command (matches the SMA-328 `BashTool`).
28	pub const DEFAULT_TIMEOUT: Duration = Duration::from_secs(30);
29	/// Default per-stream output cap, in bytes (1 MiB).
30	pub const DEFAULT_MAX_OUTPUT: usize = 1 << 20;
31	
32	/// A backend that runs one shell command under some containment tier.
33	///
34	/// Object-safe and not generic over the agent context, so one value is shared as
35	/// `Arc<dyn ExecutionBackend>` across agents of any context type. Swapping the
36	/// backend needs no change to [`crate::BashTool`] or agent code.
37	#[async_trait]
38	pub trait ExecutionBackend: Send + Sync {
39	    /// Run `req.command` to completion under this backend's containment.
40	    async fn run(&self, req: ExecRequest) -> Result<ExecOutput, ToolError>;
41	
42	    /// What this backend actually enforces — surfaced in docs, the model-facing
43	    /// tool description, and traces. Describes *containment*, not approval.
44	    fn guarantees(&self) -> SandboxGuarantees;
45	}
46	
47	/// A request to run one shell command. `#[non_exhaustive]` so per-call knobs
48	/// (stdin, env overrides) can be added later without a breaking change.
49	#[derive(Debug, Clone)]
50	#[non_exhaustive]
51	pub struct ExecRequest {
52	    /// The shell command (`sh -c <command>` on unix, `cmd /C` on Windows).
53	    pub command: String,
54	}
55	
56	impl ExecRequest {
57	    /// Build a request from a command string.
58	    pub fn new(command: impl Into<String>) -> Self {
59	        Self {
60	            command: command.into(),
61	        }
62	    }
63	}
64	
65	/// The captured result of one command run. Non-zero exit, timeout, and
66	/// truncation are *normal results* the model inspects — never errors.
67	#[derive(Debug, Clone)]
68	#[non_exhaustive]
69	pub struct ExecOutput {
70	    /// Captured stdout (lossy UTF-8, truncated at the backend's output cap).
71	    pub stdout: String,
72	    /// Captured stderr (lossy UTF-8, truncated at the backend's output cap).
73	    pub stderr: String,
74	    /// Process exit code, or `None` if killed by signal / timeout.
75	    pub exit_code: Option<i32>,
76	    /// Whether the command was killed because it exceeded the timeout.
77	    pub timed_out: bool,
78	    /// Whether either stream was truncated at the output cap.
79	    pub truncated: bool,
80	}
81	
82	impl ExecOutput {
83	    /// Construct an `ExecOutput` from all fields.
84	    pub fn new(
85	        stdout: String,
86	        stderr: String,
87	        exit_code: Option<i32>,
88	        timed_out: bool,
89	        truncated: bool,
90	    ) -> Self {
91	        Self {
92	            stdout,
93	            stderr,
94	            exit_code,
95	            timed_out,
96	            truncated,
97	        }
98	    }
99	}
