101	/// The isolation level enforced on one axis (filesystem / network / syscalls).
102	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
103	#[non_exhaustive]
104	pub enum Isolation {
105	    /// No OS enforcement — the command has the same access this process does.
106	    None,
107	    /// Enforced by an OS kernel mechanism (Landlock / seccomp-bpf).
108	    OsKernel,
109	}
110	
111	/// What a backend enforces, surfaced to docs / traces / the tool description.
112	#[derive(Debug, Clone)]
113	#[non_exhaustive]
114	pub struct SandboxGuarantees {
115	    /// Filesystem containment.
116	    pub filesystem: Isolation,
117	    /// Network containment.
118	    pub network: Isolation,
119	    /// Syscall containment.
120	    pub syscalls: Isolation,
121	    /// Short human label, e.g. `"host (no containment)"`.
122	    pub label: &'static str,
123	}
124	
125	impl SandboxGuarantees {
126	    /// Construct a `SandboxGuarantees` from all axes.
127	    pub fn new(
128	        filesystem: Isolation,
129	        network: Isolation,
130	        syscalls: Isolation,
131	        label: &'static str,
132	    ) -> Self {
133	        Self {
134	            filesystem,
135	            network,
136	            syscalls,
137	            label,
138	        }
139	    }
140	}
