142	/// Resource limits applied to a command via `setrlimit` (unix). Each `None`
143	/// leaves the inherited limit. See `HostBackend` for the default policy.
144	///
145	/// Not `#[non_exhaustive]`: this is user-built config (struct-literal
146	/// construction from consumer code and integration tests); adding a field later
147	/// is an accepted 0.x breaking change.
148	#[derive(Debug, Clone, Default)]
149	pub struct ResourceLimits {
150	    /// `RLIMIT_CPU` — CPU seconds.
151	    pub cpu_seconds: Option<u64>,
152	    /// `RLIMIT_FSIZE` — max bytes a single file write may reach.
153	    pub file_size_bytes: Option<u64>,
154	    /// `RLIMIT_AS` — virtual address-space cap. Approximate; off by default
155	    /// because it spuriously kills threaded/`mmap`-heavy programs.
156	    pub address_space_bytes: Option<u64>,
157	}
158	
159	/// Internal config every backend shares; consumed by [`spawn_capped`].
160	pub(crate) struct ExecConfig {
161	    pub(crate) cwd: PathBuf,
162	    pub(crate) env_allowlist: Vec<String>,
163	    pub(crate) timeout: Duration,
164	    pub(crate) max_output_bytes: usize,
165	}
