167	use std::process::Stdio;
168	use tokio::io::AsyncReadExt;
169	
170	/// Grace period for reaping a killed process and draining its pipes.
171	const GRACE: Duration = Duration::from_secs(5);
172	
173	/// Spawn `command` under `cfg`, draining stdout/stderr concurrently, killing the
174	/// whole process group on timeout. `configure_child` runs in the **parent** to
175	/// install backend-specific `pre_exec` hooks before spawn.
176	pub(crate) async fn spawn_capped(
177	    cfg: &ExecConfig,
178	    command: &str,
179	    configure_child: impl FnOnce(&mut tokio::process::Command),
180	) -> Result<ExecOutput, ToolError> {
181	    let mut cmd = build_command(command);
182	    cmd.current_dir(&cfg.cwd)
183	        .env_clear()
184	        .stdin(Stdio::null())
185	        .stdout(Stdio::piped())
186	        .stderr(Stdio::piped());
187	    for name in &cfg.env_allowlist {
188	        if let Ok(val) = std::env::var(name) {
189	            cmd.env(name, val);
190	        }
191	    }
192	    #[cfg(unix)]
193	    {
194	        // New process group so a timeout can kill the whole subtree.
195	        cmd.process_group(0);
196	    }
197	    configure_child(&mut cmd);
198	
199	    let mut child = cmd
200	        .spawn()
201	        .map_err(|e| ToolError::Other(anyhow::anyhow!("failed to spawn shell: {e}")))?;
202	
203	    #[cfg(unix)]
204	    let pgid = child.id();
205	
206	    let stdout_pipe = child.stdout.take().expect("piped stdout");
207	    let stderr_pipe = child.stderr.take().expect("piped stderr");
208	
209	    let cap = cfg.max_output_bytes;
210	    let out_handle = tokio::spawn(read_capped(stdout_pipe, cap));
211	    let err_handle = tokio::spawn(read_capped(stderr_pipe, cap));
212	
213	    let mut timed_out = false;
214	    let exit_code: Option<i32>;
215	    match tokio::time::timeout(cfg.timeout, child.wait()).await {
216	        Ok(status) => {
217	            exit_code = status.map_err(|e| ToolError::Other(e.into()))?.code();
218	        }
219	        Err(_) => {
220	            timed_out = true;
221	            #[cfg(unix)]
222	            {
223	                if let Some(pid) = pgid {
224	                    // SAFETY: pid < 4_194_304 on supported platforms, so the cast
225	                    // and negation are valid; ESRCH (group already gone) is benign.
226	                    let _ = unsafe { libc::kill(-(pid as i32), libc::SIGKILL) };
227	                }
228	            }
229	            #[cfg(not(unix))]
230	            {
231	                let _ = child.start_kill();
232	            }
233	            exit_code = match tokio::time::timeout(GRACE, child.wait()).await {
234	                Ok(Ok(status)) => status.code(),
235	                _ => None,
236	            };
237	        }
238	    }
239	
240	    let ((stdout, out_trunc), (stderr, err_trunc)) =
241	        tokio::join!(join_reader(out_handle), join_reader(err_handle));
242	
243	    Ok(ExecOutput {
244	        stdout,
245	        stderr,
246	        exit_code,
247	        timed_out,
248	        truncated: out_trunc || err_trunc,
249	    })
250	}
251	
252	/// Build the platform shell command without yet setting cwd/env.
253	fn build_command(command: &str) -> tokio::process::Command {
254	    #[cfg(unix)]
255	    {
256	        let mut c = tokio::process::Command::new("sh");
257	        c.arg("-c").arg(command);
258	        c
259	    }
260	    #[cfg(windows)]
261	    {
262	        let mut c = tokio::process::Command::new("cmd");
263	        c.arg("/C").arg(command);
264	        c
265	    }
266	}
267	
268	async fn join_reader(handle: tokio::task::JoinHandle<(String, bool)>) -> (String, bool) {
269	    let abort = handle.abort_handle();
270	    match tokio::time::timeout(GRACE, handle).await {
271	        Ok(Ok(captured)) => captured,
272	        _ => {
273	            abort.abort();
274	            (String::new(), false)
275	        }
276	    }
277	}
278	
279	async fn read_capped<R>(pipe: R, cap: usize) -> (String, bool)
280	where
281	    R: tokio::io::AsyncRead + Unpin + Send + 'static,
282	{
283	    let mut buf = Vec::new();
284	    let _ = pipe.take((cap as u64) + 1).read_to_end(&mut buf).await;
285	    let truncated = buf.len() > cap;
286	    buf.truncate(cap);
287	    (String::from_utf8_lossy(&buf).into_owned(), truncated)
288	}
289	
290	/// Apply `limits` to the current process via `setrlimit`. Async-signal-safe
291	/// (only `setrlimit` syscalls, no allocation) so it is callable from `pre_exec`.
292	#[cfg(unix)]
293	pub(crate) fn apply_rlimits(limits: &ResourceLimits) -> std::io::Result<()> {
294	    // SAFETY: setrlimit with a stack-allocated rlimit is async-signal-safe.
295	    unsafe {
296	        // The resource arg's type differs per target (`c_int` on macOS/BSD/musl,
297	        // `__rlimit_resource_t` on Linux glibc), so it is inferred from the
298	        // platform's `RLIMIT_*` constants rather than fixed to one type.
299	        let set = |res, val: u64| -> std::io::Result<()> {
300	            let rl = libc::rlimit {
301	                rlim_cur: val as libc::rlim_t,
302	                rlim_max: val as libc::rlim_t,
303	            };
304	            if libc::setrlimit(res, &rl) != 0 {
305	                return Err(std::io::Error::last_os_error());
306	            }
307	            Ok(())
308	        };
309	        if let Some(s) = limits.cpu_seconds {
310	            set(libc::RLIMIT_CPU, s)?;
311	        }
312	        if let Some(b) = limits.file_size_bytes {
313	            set(libc::RLIMIT_FSIZE, b)?;
314	        }
315	        if let Some(b) = limits.address_space_bytes {
316	            set(libc::RLIMIT_AS, b)?;
317	        }
318	    }
319	    Ok(())
320	}
