1	//! [`OsSandboxBackend`] — OS-enforced Bash containment on Linux via Landlock
2	//! (filesystem) + seccomp-bpf (syscalls / network). Fail-closed: `build()` errors
3	//! if the kernel cannot enforce the requested isolation.
4	
5	use std::collections::BTreeMap;
6	use std::path::PathBuf;
7	use std::sync::Arc;
8	use std::time::Duration;
9	
10	use async_trait::async_trait;
11	use landlock::{
12	    path_beneath_rules, Access, AccessFs, CompatLevel, Compatible, Ruleset, RulesetAttr,
13	    RulesetCreatedAttr, RulesetStatus, ABI,
14	};
15	use paigasus_helikon_core::ToolError;
16	use seccompiler::{
17	    apply_filter, BpfProgram, SeccompAction, SeccompCmpArgLen, SeccompCmpOp, SeccompCondition,
18	    SeccompFilter, SeccompRule, TargetArch,
19	};
20	
21	use super::{
22	    spawn_capped, ExecConfig, ExecOutput, ExecRequest, ExecutionBackend, Isolation, ResourceLimits,
23	    SandboxGuarantees, DEFAULT_MAX_OUTPUT, DEFAULT_TIMEOUT,
24	};
25	use crate::sandbox::Sandbox;
26	
27	/// Landlock ABI floor we require for filesystem containment (kernel ≥ 5.13).
28	const LANDLOCK_ABI: ABI = ABI::V1;
29	
30	/// Target arch for the seccomp BPF. The `os_sandbox` module is gated to these two
31	/// arches (see `super::os_sandbox` cfg), so exactly one of these is compiled.
32	#[cfg(target_arch = "x86_64")]
33	const SECCOMP_ARCH: TargetArch = TargetArch::x86_64;
34	#[cfg(target_arch = "aarch64")]
35	const SECCOMP_ARCH: TargetArch = TargetArch::aarch64;
36	
37	/// Construction failures for [`OsSandboxBackend`]. Distinct from
38	/// `ToolError::Denied` (an in-`run` refusal) and from `SandboxError`.
39	#[derive(Debug, thiserror::Error)]
40	#[non_exhaustive]
41	pub enum OsSandboxError {
42	    /// The kernel cannot enforce Landlock at the required ABI.
43	    #[error("OS sandbox unavailable: {0}")]
44	    Unsupported(String),
45	}
46	
47	/// Builder for [`OsSandboxBackend`].
48	pub struct OsSandboxBackendBuilder {
49	    sandbox: Sandbox,
50	    timeout: Duration,
51	    env_allowlist: Vec<String>,
52	    max_output_bytes: usize,
53	    limits: ResourceLimits,
54	    allow_network: bool,
55	    read_paths: Vec<PathBuf>,
56	}
57	
58	impl OsSandboxBackendBuilder {
59	    /// Wall-clock timeout before the process group is killed (default 30s).
60	    pub fn timeout(mut self, timeout: Duration) -> Self {
61	        self.timeout = timeout;
62	        self
63	    }
64	    /// Env var names to pass through (REPLACES the default `["PATH","HOME"]`).
65	    pub fn env_allowlist<I, S>(mut self, names: I) -> Self
66	    where
67	        I: IntoIterator<Item = S>,
68	        S: Into<String>,
69	    {
70	        self.env_allowlist = names.into_iter().map(Into::into).collect();
71	        self
72	    }
73	    /// Truncate captured stdout/stderr to this many bytes each (default 1 MiB).
74	    pub fn max_output_bytes(mut self, n: usize) -> Self {
75	        self.max_output_bytes = n;
76	        self
77	    }
78	    /// Override resource limits applied inside the jail.
79	    pub fn rlimits(mut self, limits: ResourceLimits) -> Self {
80	        self.limits = limits;
81	        self
82	    }
83	    /// Allow outbound network (default: deny all IP egress).
84	    pub fn allow_network(mut self, allow: bool) -> Self {
85	        self.allow_network = allow;
86	        self
87	    }
88	    /// Extra read-only path exceptions beyond the default system set.
89	    pub fn read_paths<I, P>(mut self, paths: I) -> Self
90	    where
91	        I: IntoIterator<Item = P>,
92	        P: Into<PathBuf>,
93	    {
94	        self.read_paths = paths.into_iter().map(Into::into).collect();
95	        self
96	    }
97	
98	    /// Finish building. **Fail-closed:** returns `Err` if Landlock cannot be
99	    /// enforced at the required ABI (v1; kernel ≥ 5.13) on this host.
100	    pub fn build(self) -> Result<Arc<dyn ExecutionBackend>, OsSandboxError> {
101	        probe_landlock()?;
102	        Ok(Arc::new(OsSandboxBackend {
103	            cfg: ExecConfig {
104	                cwd: self.sandbox.root().to_path_buf(),
105	                env_allowlist: self.env_allowlist,
106	                timeout: self.timeout,
107	                max_output_bytes: self.max_output_bytes,
108	            },
109	            limits: self.limits,
110	            allow_network: self.allow_network,
111	            root: self.sandbox.root().to_path_buf(),
112	            read_paths: self.read_paths,
113	        }))
114	    }
115	}
116	
117	/// Probe Landlock support without restricting the current process: create a
118	/// ruleset fd under a hard-requirement compat level and drop it.
119	fn probe_landlock() -> Result<(), OsSandboxError> {
120	    Ruleset::default()
121	        .set_compatibility(CompatLevel::HardRequirement)
122	        .handle_access(AccessFs::from_all(LANDLOCK_ABI))
123	        .and_then(|r| r.create())
124	        .map(|_created| ())
125	        .map_err(|e| OsSandboxError::Unsupported(e.to_string()))
126	}
127	
128	/// Read-only system paths a shell + common tools need. (`/usr/sbin` is covered
129	/// by `/usr`; `/sbin` is listed for distros that have not usr-merged it.)
130	const SYSTEM_RO: &[&str] = &["/usr", "/bin", "/sbin", "/lib", "/lib64", "/etc"];
131	
132	/// Build (in the parent) a Landlock ruleset: read+write under the sandbox root,
133	/// read+exec for the system paths and any extra `read_paths`.
134	fn build_ruleset(
135	    root: &std::path::Path,
136	    read_paths: &[PathBuf],
137	) -> Result<landlock::RulesetCreated, landlock::RulesetError> {
138	    let abi = LANDLOCK_ABI;
139	    let ro: Vec<PathBuf> = SYSTEM_RO
140	        .iter()
141	        .map(PathBuf::from)
142	        .chain(read_paths.iter().cloned())
143	        .filter(|p| p.exists())
144	        .collect();
145	    Ruleset::default()
146	        .set_compatibility(CompatLevel::HardRequirement)
147	        .handle_access(AccessFs::from_all(abi))?
148	        .create()?
149	        .add_rules(path_beneath_rules(&ro, AccessFs::from_read(abi)))?
150	        .add_rules(path_beneath_rules([root], AccessFs::from_all(abi)))
151	}
152	
153	/// Compile (in the parent) a seccomp filter: allow by default, return EPERM for a
154	/// dangerous syscall set; when `allow_network` is false also EPERM `socket()` for
155	/// `AF_INET`/`AF_INET6` (`AF_UNIX` stays allowed).
156	fn build_seccomp(allow_network: bool) -> Result<BpfProgram, ToolError> {
157	    // The `backend` constructors (`SeccompCondition/Rule/Filter::new`, the
158	    // `BpfProgram` `TryFrom`) all surface `seccompiler::BackendError`, NOT the
159	    // top-level `seccompiler::Error` (that one is for `apply_filter`).
160	    let err = |e: seccompiler::BackendError| ToolError::Other(anyhow::anyhow!("seccomp: {e}"));
161	    let mut rules: BTreeMap<i64, Vec<SeccompRule>> = BTreeMap::new();
162	
163	    // Always-deny dangerous syscalls (empty rule vec = match regardless of args).
164	    for sc in [
165	        libc::SYS_ptrace,
166	        libc::SYS_mount,
167	        libc::SYS_umount2,
168	        libc::SYS_pivot_root,
169	        libc::SYS_chroot,
170	        libc::SYS_setns,
171	        libc::SYS_unshare,
172	        libc::SYS_kexec_load,
173	        libc::SYS_bpf,
174	        libc::SYS_perf_event_open,
175	    ] {
176	        rules.insert(sc, vec![]);
177	    }
178	
179	    if !allow_network {
180	        // Match `socket(family, ..)` for AF_INET / AF_INET6 (arg0); AF_UNIX is
181	        // left allowed so local IPC and `/dev/log`-style sockets keep working.
182	        // x86_64/aarch64 use the direct `socket` syscall, so this is the egress
183	        // chokepoint. (The x32 ABI ORs a bit into the syscall number and would
184	        // slip past, but standard amd64 userland — including CI — ships no x32
185	        // binaries, so it is out of scope.)
186	        let af = |family: u64| -> Result<SeccompRule, ToolError> {
187	            SeccompRule::new(vec![SeccompCondition::new(
188	                0,
189	                SeccompCmpArgLen::Dword,
190	                SeccompCmpOp::Eq,
191	                family,
192	            )
193	            .map_err(err)?])
194	            .map_err(err)
195	        };
196	        rules.insert(
197	            libc::SYS_socket,
198	            vec![af(libc::AF_INET as u64)?, af(libc::AF_INET6 as u64)?],
199	        );
200	    }
201	
202	    let filter = SeccompFilter::new(
203	        rules,
204	        SeccompAction::Allow,                     // default: allow
205	        SeccompAction::Errno(libc::EPERM as u32), // on match: EPERM
206	        SECCOMP_ARCH,
207	    )
208	    .map_err(err)?;
209	    filter.try_into().map_err(err)
210	}
211	
212	/// OS-enforced execution backend (Linux). See module docs.
213	pub struct OsSandboxBackend {
214	    cfg: ExecConfig,
215	    limits: ResourceLimits,
216	    allow_network: bool,
217	    root: PathBuf,
218	    read_paths: Vec<PathBuf>,
219	}
220	
221	impl OsSandboxBackend {
222	    /// Start building over `sandbox` (read+write root; default deny-network).
223	    pub fn builder(sandbox: Sandbox) -> OsSandboxBackendBuilder {
224	        OsSandboxBackendBuilder {
225	            sandbox,
226	            timeout: DEFAULT_TIMEOUT,
227	            env_allowlist: vec!["PATH".to_owned(), "HOME".to_owned()],
228	            max_output_bytes: DEFAULT_MAX_OUTPUT,
229	            limits: ResourceLimits::default(),
230	            allow_network: false,
231	            read_paths: Vec::new(),
232	        }
233	    }
234	}
235	
236	#[async_trait]
237	impl ExecutionBackend for OsSandboxBackend {
238	    async fn run(&self, req: ExecRequest) -> Result<ExecOutput, ToolError> {
239	        let limits = self.limits.clone();
240	        // Built in the PARENT (allocations are safe here, not in the child).
241	        let ruleset = build_ruleset(&self.root, &self.read_paths)
242	            .map_err(|e| ToolError::Other(anyhow::anyhow!("landlock ruleset: {e}")))?;
243	        let mut ruleset = Some(ruleset);
244	        // Compile the seccomp BPF in the PARENT too (BTreeMap/Vec allocation is
245	        // not async-signal-safe and must not happen in the forked child).
246	        let seccomp = build_seccomp(self.allow_network)?;
247	
248	        spawn_capped(&self.cfg, &req.command, move |cmd| {
249	            // SAFETY: the closure runs in the forked child before exec, so it does
250	            // only async-signal-safe work — no heap allocation, no locks: the
251	            // `setrlimit` syscalls in `apply_rlimits`, then Landlock's
252	            // `restrict_self` (`prctl(PR_SET_NO_NEW_PRIVS)` + `landlock_restrict_self`
253	            // on an already-created ruleset fd, plus a small stack struct), then
254	            // `apply_filter` (a `prctl(PR_SET_SECCOMP)` syscall over the pre-compiled
255	            // BPF). The `RulesetCreated` and `BpfProgram` are built in the parent and
256	            // moved in; the ruleset is taken via `Option::take` so it applies once.
257	            unsafe {
258	                cmd.pre_exec(move || {
259	                    super::apply_rlimits(&limits)?;
260	                    if let Some(rs) = ruleset.take() {
261	                        let status = rs
262	                            .restrict_self()
263	                            .map_err(|e| std::io::Error::other(e.to_string()))?;
264	                        // Fail-closed: accept only full enforcement. Anything less
265	                        // (a future ABI making Partial reachable) aborts the exec
266	                        // rather than running under weaker containment than claimed.
267	                        if status.ruleset != RulesetStatus::FullyEnforced {
268	                            return Err(std::io::Error::other("landlock not fully enforced"));
269	                        }
270	                    }
271	                    // Applied after Landlock. An unprivileged seccomp install needs
272	                    // PR_SET_NO_NEW_PRIVS, which `restrict_self` sets — though
273	                    // `apply_filter` also sets it itself, so this is not a strict
274	                    // seccomp prerequisite; we order Landlock first for its own
275	                    // semantics.
276	                    apply_filter(&seccomp).map_err(|e| std::io::Error::other(e.to_string()))?;
277	                    Ok(())
278	                });
279	            }
280	        })
281	        .await
282	    }
283	
284	    fn guarantees(&self) -> SandboxGuarantees {
285	        SandboxGuarantees {
286	            filesystem: Isolation::OsKernel,
287	            network: if self.allow_network {
288	                Isolation::None
289	            } else {
290	                Isolation::OsKernel
291	            },
292	            syscalls: Isolation::OsKernel,
293	            label: "os-sandbox (landlock+seccomp)",
294	        }
295	    }
296	}
