2	//! scrubbing, an output cap, a timeout (process-group kill), and `rlimit`s.
3	//! **NOT a security boundary:** a spawned command can read/write anything this
4	//! process can. Gate it with a `PermissionPolicy` or use [`OsSandboxBackend`]
5	//! for OS-enforced containment.
6	
7	use std::sync::Arc;
8	use std::time::Duration;
9	
10	use async_trait::async_trait;
11	use paigasus_helikon_core::ToolError;
12	
13	use super::{
14	    spawn_capped, ExecConfig, ExecOutput, ExecRequest, ExecutionBackend, Isolation, ResourceLimits,
15	    SandboxGuarantees, DEFAULT_MAX_OUTPUT, DEFAULT_TIMEOUT,
16	};
17	use crate::sandbox::Sandbox;
18	
19	/// Default `RLIMIT_FSIZE` cap: 1 GiB.
20	const DEFAULT_FILE_SIZE_LIMIT: u64 = 1 << 30;
21	/// Extra CPU seconds granted over the wall timeout for the `RLIMIT_CPU` backstop.
22	const CPU_LIMIT_MARGIN_SECS: u64 = 5;
23	
24	/// Builder for [`HostBackend`].
25	pub struct HostBackendBuilder {
26	    sandbox: Sandbox,
27	    timeout: Duration,
28	    env_allowlist: Vec<String>,
29	    max_output_bytes: usize,
30	    limits: ResourceLimits,
31	    limits_set: bool,
32	}
33	
34	impl HostBackendBuilder {
35	    /// Wall-clock timeout before the process group is killed (default 30s).
36	    pub fn timeout(mut self, timeout: Duration) -> Self {
37	        self.timeout = timeout;
38	        self
39	    }
40	
41	    /// Env var names to pass through (REPLACES the default `["PATH","HOME"]`).
42	    pub fn env_allowlist<I, S>(mut self, names: I) -> Self
43	    where
44	        I: IntoIterator<Item = S>,
45	        S: Into<String>,
46	    {
47	        self.env_allowlist = names.into_iter().map(Into::into).collect();
48	        self
49	    }
50	
51	    /// Truncate captured stdout/stderr to this many bytes each (default 1 MiB).
52	    pub fn max_output_bytes(mut self, n: usize) -> Self {
53	        self.max_output_bytes = n;
54	        self
55	    }
56	
57	    /// Override the resource limits. Replaces the defaults
58	    /// (`RLIMIT_CPU` = timeout+5s, `RLIMIT_FSIZE` = 1 GiB, `RLIMIT_AS` = unset).
59	    pub fn rlimits(mut self, limits: ResourceLimits) -> Self {
60	        self.limits = limits;
61	        self.limits_set = true;
62	        self
63	    }
64	
65	    /// Finish building, returning a shareable `Arc<dyn ExecutionBackend>`.
66	    pub fn build(mut self) -> Arc<dyn ExecutionBackend> {
67	        if !self.limits_set {
68	            // Default policy: CPU backstop derived from the timeout, a generous
69	            // file-size cap, address-space cap left off (review M2).
70	            self.limits = ResourceLimits {
71	                cpu_seconds: Some(self.timeout.as_secs().saturating_add(CPU_LIMIT_MARGIN_SECS)),
72	                file_size_bytes: Some(DEFAULT_FILE_SIZE_LIMIT),
73	                address_space_bytes: None,
74	            };
75	        }
76	        Arc::new(HostBackend {
77	            cfg: ExecConfig {
78	                cwd: self.sandbox.root().to_path_buf(),
79	                env_allowlist: self.env_allowlist,
80	                timeout: self.timeout,
81	                max_output_bytes: self.max_output_bytes,
82	            },
83	            limits: self.limits,
84	        })
85	    }
86	}
