95	impl HostBackend {
96	    /// Start building a `HostBackend` over `sandbox` (cwd = `sandbox.root()`),
97	    /// with a 30s timeout, `["PATH","HOME"]` env allowlist, 1 MiB output cap.
98	    pub fn builder(sandbox: Sandbox) -> HostBackendBuilder {
99	        HostBackendBuilder {
100	            sandbox,
101	            timeout: DEFAULT_TIMEOUT,
102	            env_allowlist: vec!["PATH".to_owned(), "HOME".to_owned()],
103	            max_output_bytes: DEFAULT_MAX_OUTPUT,
104	            limits: ResourceLimits::default(),
105	            limits_set: false,
106	        }
107	    }
108	}
