110	#[async_trait]
111	impl ExecutionBackend for HostBackend {
112	    async fn run(&self, req: ExecRequest) -> Result<ExecOutput, ToolError> {
113	        let limits = self.limits.clone();
114	        spawn_capped(&self.cfg, &req.command, move |_cmd| {
115	            #[cfg(unix)]
116	            {
117	                // SAFETY: apply_rlimits is async-signal-safe (setrlimit only).
118	                unsafe {
119	                    _cmd.pre_exec(move || super::apply_rlimits(&limits));
120	                }
121	            }
122	        })
123	        .await
124	    }
