126	    fn guarantees(&self) -> SandboxGuarantees {
127	        SandboxGuarantees {
128	            filesystem: Isolation::None,
129	            network: Isolation::None,
130	            syscalls: Isolation::None,
131	            label: "host (no containment)",
132	        }
133	    }
134	}
